use horizon_client::mobs::model_layers::{CubeDeformation, CubeListBuilder, LayerDefinition, MeshDefinition, ModelPart, PartPose};
pub(super) fn adult() -> ModelPart {
    let mut mesh = MeshDefinition::new();
    let partdefinition = mesh.root();
    let root = mesh.add_or_replace_child(partdefinition, "root", CubeListBuilder::create(), PartPose::offset(0.0, 24.0, 0.0));
    let body = mesh.add_or_replace_child(root, "body", CubeListBuilder::create().tex_offs(0, 0).add_box_with([-5.0, -4.0, -11.0], [10.0, 8.0, 22.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, -7.0, 6.0));
    let neck = mesh.add_or_replace_child(body, "neck", CubeListBuilder::create().tex_offs(71, 71).add_box_with([-5.0, -3.0, -4.0], [10.0, 6.0, 6.0], CubeDeformation::new(-0.02)), PartPose::offset(0.0, -1.0, -11.0));
    let skull = mesh.add_or_replace_child(neck, "skull", CubeListBuilder::create().tex_offs(0, 0).add_box_with([-3.0, -2.5, -5.0], [6.0, 3.0, 3.0], CubeDeformation::new(0.0)).tex_offs(42, 0).add_box_with([-3.0, -2.5, -2.0], [6.0, 3.0, 2.0], CubeDeformation::new(0.0)).tex_offs(58, 0).add_box_with([-3.0, 0.5, -2.0], [6.0, 3.0, 2.0], CubeDeformation::new(0.0)).tex_offs(66, 0).add_box_with([-3.0, -2.5, -13.0], [6.0, 3.0, 8.0], CubeDeformation::new(0.0)).tex_offs(54, 30).add_box_with([-3.0, 0.5, -12.0], [6.0, 1.0, 8.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, -0.5, -4.0));
    let lower_jaw = mesh.add_or_replace_child(skull, "lower_jaw", CubeListBuilder::create().tex_offs(86, 0).add_box_with([-3.0, 0.0, -3.0], [6.0, 3.0, 3.0], CubeDeformation::new(0.02)).tex_offs(44, 82).add_box_with([-3.0, -3.0, -3.0], [6.0, 3.0, 3.0], CubeDeformation::new(-0.02)).tex_offs(96, 0).add_box_with([-3.0, 0.0, -11.0], [6.0, 1.0, 8.0], CubeDeformation::new(0.0)).tex_offs(58, 43).add_box_with([-3.0, -1.0, -10.0], [6.0, 1.0, 8.0], CubeDeformation::new(-0.02)), PartPose::offset(0.0, 0.5, -2.0));
    let tail = mesh.add_or_replace_child(body, "tail", CubeListBuilder::create().tex_offs(0, 30).add_box_with([-3.0, -2.0169, -0.0949], [6.0, 5.0, 12.0], CubeDeformation::new(0.0)), PartPose::offset_and_rotation(0.0, -2.0, 11.0, -0.3927, 0.0, 0.0));
    let tail2 = mesh.add_or_replace_child(tail, "tail2", CubeListBuilder::create().tex_offs(65, 12).add_box_with([-1.5, -2.0, 0.0], [3.0, 4.0, 14.0], CubeDeformation::new(0.0)), PartPose::offset_and_rotation(0.0, 0.9831, 11.9051, 0.2618, 0.0, 0.0));
    let legs = mesh.add_or_replace_child(root, "legs", CubeListBuilder::create(), PartPose::offset(5.0, -5.25, -2.0));
    let left_arm = mesh.add_or_replace_child(legs, "left_arm", CubeListBuilder::create().tex_offs(42, 57).add_box_with([-1.0, -1.75, -2.0], [4.0, 7.0, 4.0], CubeDeformation::new(0.0)).tex_offs(59, 59).add_box_with([-1.0, 3.25, -4.0], [4.0, 2.0, 2.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, 0.0, 0.0));
    let right_arm = mesh.add_or_replace_child(legs, "right_arm", CubeListBuilder::create().tex_offs(42, 57).set_mirror(true).add_box_with([-3.0, -1.75, -2.0], [4.0, 7.0, 4.0], CubeDeformation::new(0.0)).set_mirror(false).tex_offs(59, 59).set_mirror(true).add_box_with([-3.0, 3.25, -4.0], [4.0, 2.0, 2.0], CubeDeformation::new(0.0)).set_mirror(false), PartPose::offset(-10.0, 0.0, 0.0));
    let left_leg = mesh.add_or_replace_child(legs, "left_leg", CubeListBuilder::create().tex_offs(59, 59).add_box_with([-2.0, 3.75, -4.5], [4.0, 2.0, 2.0], CubeDeformation::new(0.0)).tex_offs(0, 51).add_box_with([-2.0, -3.25, -2.5], [4.0, 9.0, 6.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, -0.5, 16.5));
    let right_leg = mesh.add_or_replace_child(legs, "right_leg", CubeListBuilder::create().tex_offs(59, 59).set_mirror(true).add_box_with([-2.0, 3.75, -4.5], [4.0, 2.0, 2.0], CubeDeformation::new(0.0)).set_mirror(false).tex_offs(0, 51).set_mirror(true).add_box_with([-2.0, -3.25, -2.5], [4.0, 9.0, 6.0], CubeDeformation::new(0.0)).set_mirror(false), PartPose::offset(-10.0, -0.5, 16.5));
    LayerDefinition::create(mesh, 128, 128).bake_root()
}
